import java.util.Arrays;

public class SolutionTest {
    public static void main(String[] args) {
        String name = "  Release One  ";
        String[] tags = {"alpha", " spaced tag ", ""};
        Solution.Snapshot snapshot = Solution.createSnapshot(name, tags);
        assertEquals(name, snapshot.getName(), "name preserved exactly");
        assertArrayEquals(new String[]{"alpha", " spaced tag ", ""}, snapshot.getTags(),
                "tags preserved exactly");

        tags[0] = "caller mutation";
        assertEquals("alpha", snapshot.getTags()[0],
                "caller array mutation does not affect snapshot");

        String[] firstRead = snapshot.getTags();
        String[] secondRead = snapshot.getTags();
        assertTrue(firstRead != secondRead, "each getTags call returns a new array");
        firstRead[1] = "getter mutation";
        assertEquals(" spaced tag ", snapshot.getTags()[1],
                "returned array mutation does not affect snapshot");

        Solution.Snapshot empty = Solution.createSnapshot("valid", new String[0]);
        String[] emptyFirst = empty.getTags();
        String[] emptySecond = empty.getTags();
        assertEquals(0, emptyFirst.length, "empty tags allowed");
        assertTrue(emptyFirst != emptySecond, "empty tag getters are also independent");

        expectThrows(IllegalArgumentException.class,
                () -> Solution.createSnapshot(null, new String[0]));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.createSnapshot("", new String[0]));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.createSnapshot(" \n\t", new String[0]));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.createSnapshot("name", null));
        expectThrows(IllegalArgumentException.class,
                () -> Solution.createSnapshot("name", new String[]{"ok", null}));
    }

    private static void assertArrayEquals(String[] expected, String[] actual, String message) {
        if (!Arrays.equals(expected, actual)) {
            throw new AssertionError(message + ": expected=" + Arrays.toString(expected)
                    + ", actual=" + Arrays.toString(actual));
        }
    }

    private static void assertEquals(int expected, int actual, String message) {
        if (expected != actual) throw new AssertionError(message);
    }

    private static void assertEquals(String expected, String actual, String message) {
        if (!expected.equals(actual)) {
            throw new AssertionError(message + ": expected=" + expected + ", actual=" + actual);
        }
    }

    private static void assertTrue(boolean condition, String message) {
        if (!condition) throw new AssertionError(message);
    }

    private static void expectThrows(Class<? extends Throwable> type, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (type.isInstance(error)) return;
            throw new AssertionError("Expected " + type.getName() + " but got " + error, error);
        }
        throw new AssertionError("Expected " + type.getName() + " to be thrown");
    }
}

